def main():
    s = sys.stdin.readline().strip()
    out = []
    w = 0  # number of trailing W's in out
    for c in s:
        if c == 'W':
            out.append('W')
            w += 1
        elif c == 'A':
            if w > 0:
                del out[len(out) - w:]
                out.append('A')
                out.extend('C' * w)
                w = 0
            else:
                out.append('A')
        else:
            out.append(c)
            w = 0
    sys.stdout.write(''.join(out) + '\n')

